<?php
require_once __DIR__.'/core/bootstrap.php';require_once __DIR__.'/core/page-designer.php';ag_no_cache();header('Content-Type: application/json; charset=utf-8');
try{if(session_status()!==PHP_SESSION_ACTIVE)session_start();$session=ag_current_session();$method=$_SERVER['REQUEST_METHOD'] ?? 'GET';$page=$method==='POST'?($_POST['page'] ?? ''):($_GET['page'] ?? '');$form=$method==='POST'?($_POST['form'] ?? ''):($_GET['form'] ?? '');
    if($method==='GET')$result=ag_pf_challenge($page,$form,$session);
    elseif($method==='POST'){if((int)($_SERVER['CONTENT_LENGTH'] ?? 0)>600000)throw new RuntimeException('The form request is too large.',413);$origin=$_SERVER['HTTP_ORIGIN'] ?? '';if($origin!==''){$parts=parse_url($origin);$authority=strtolower(($parts['host'] ?? '').(isset($parts['port'])?':'.$parts['port']:''));if($authority!==strtolower($_SERVER['HTTP_HOST'] ?? '')||!in_array($parts['scheme'] ?? '',array('http','https'),true))throw new RuntimeException('Access denied.',403);}
        $values=json_decode($_POST['values'] ?? '',true);$result=ag_pf_accept($page,$form,$_POST['token'] ?? '',$values,$_POST['company_website'] ?? '',$session,$_SERVER['REMOTE_ADDR'] ?? '');session_write_close();if($result['handling']!=='local'){try{ag_pf_delivery($result['id']);}catch(Throwable $deliveryError){error_log('Page Designer form: delivery could not finish; message retained in the private inbox.');}}unset($result['id'],$result['handling']);
    }else throw new RuntimeException('Method not allowed.',405);echo json_encode(array('ok'=>true)+$result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
}catch(Throwable $e){$code=$e->getCode();http_response_code(in_array($code,array(403,404,405,409,413,422,429,503),true)?$code:422);echo json_encode(array('ok'=>false,'error'=>$e->getMessage()),JSON_UNESCAPED_UNICODE);}
